function AuthGate({children}){const store=useStore();const[ready,setReady]=React.useState(false);const[busy,setBusy]=React.useState(true);const[err,setErr]=React.useState("");React.useEffect(()=>{let cancelled=false;async function ensureGuestSession(){const raw=sessionStorage.getItem("pos-mesita-session");if(raw){try{const s=JSON.parse(raw);if(s?.token)return s;}catch(_){}}const res=await fetch("/sistema/api/v1/auth/guest/",{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"}});const session=await res.json().catch(()=>({}));if(!res.ok||!session?.token){throw new Error(session?.error||"No se pudo iniciar sesión demo");}sessionStorage.setItem("pos-mesita-session",JSON.stringify(session));return session;}async function boot(){setBusy(true);setErr("");try{await ensureGuestSession();if(cancelled)return;await store.init();if(cancelled)return;if(store.state.authError){throw new Error(store.state.authError);}setReady(true);}catch(e){if(!cancelled)setErr(e.message||"Error de conexión con Mesita API");}finally{if(!cancelled)setBusy(false);}}boot();return()=>{cancelled=true;};},[]);if(err){return React.createElement("div",{className:"pos-boot"},React.createElement("img",{className:"pos-boot-logo",src:"/logo.svg",alt:"",width:"64",height:"64",style:{animation:"none"}}),React.createElement("div",{className:"pos-boot-name"},"Mesita POS",React.createElement("small",null,"Consola de caja")),React.createElement("p",{style:{margin:0,maxWidth:380,color:"var(--ink-mut)",fontSize:13.5}},err),React.createElement("button",{className:"btn btn-primary",onClick:()=>window.location.reload()},"Reintentar"));}if(!ready||busy||store.state.loading){return React.createElement("div",{className:"pos-boot","aria-live":"polite"},React.createElement("img",{className:"pos-boot-logo",src:"/logo.svg",alt:"",width:"64",height:"64"}),React.createElement("div",{className:"pos-boot-name"},"Mesita POS",React.createElement("small",null,"Consola de caja")),React.createElement("div",{className:"pos-boot-bar",role:"progressbar","aria-label":"Cargando Mesita POS"}),React.createElement("div",{className:"pos-boot-msg"},"Conectando con Mesita API\u2026"));}return children;}function BootApp(){return React.createElement(AuthGate,null,React.createElement(App,null));}
